-- ############################################################
-- MIGRACIÓN DE DATOS COMPLETA · fondosco_social → Supabase
-- Municipalidad de Coinco · Departamento Social
-- Ejecutar con:  supabase db execute --file 01_migracion_datos.sql
-- Corre en UNA transacción. Al final imprime conteos (NOTICE).
-- Si algo falla, la transacción completa se revierte automáticamente.
-- ############################################################
begin;

do $$
declare v_admin uuid;
begin
  select id into v_admin from public.profiles where rol='administrador' and estado='activo' limit 1;
  if v_admin is null then raise exception 'No hay un administrador activo en profiles.'; end if;
  perform set_config('migracion.usuario', v_admin::text, false);
end $$;

-- Mapas legacy->uuid como TEMP (una sola transacción, se limpian solos al commit).
create temp table _map_hogar   (legacy_key text primary key, uuid_new uuid) on commit drop;
create temp table _map_persona (legacy_id  text primary key, uuid_new uuid) on commit drop;

-- ========== 1) GRUPOS FAMILIARES ==========
-- ============================================================
-- MIGRACIÓN DE DATOS: fondosco_social (legacy) → esquema nuevo
-- Municipalidad de Coinco · Departamento Social
-- Ejecutar en Supabase DESPUÉS de aplicar todas las migraciones de esquema.
-- Idempotente por diseño: usa tablas _map temporales para relaciones.
-- Envuelto en una transacción: si algo falla, no deja datos a medias.
-- ============================================================

