insert into public.hitos (grupo_familiar_id, persona_id, tipo, categoria, comentario, fecha_hito, creado_por)
values (
  (select uuid_new from _map_hogar where legacy_key='rsh:818'),
  (select uuid_new from _map_persona where legacy_id='818'),
  'familiar', 'familiar', 'Adulta soltera, madre de 2 hijos (1 pre adolescente, 1 adolescente), que asume cuidado integral de 2 sobrinos, siendo uno de éstos dependiente respecto a esfera de salud al padecer patología cerebral sin tratamiento ni rehabilitación. La familia presenta historial de vulnerabilidad entendiendo factores transgeneracionales de riesgo, así como también, elementos asociados a negligencia y abandono. Mantienen judicialización de causas en T. Flia Rgua; vinculados además con entidades y organizaciones sociales. Residen en vivienda de tenencia propia en sector rural, sin acceso a bienes y servicios básicos. Municipio realiza entrega de agua vía camión aljibe. Usuarios programa SNAC.', coalesce('2025-01-29'::date, current_date), current_setting('migracion.usuario')::uuid);
insert into public.hitos (grupo_familiar_id, persona_id, tipo, categoria, comentario, fecha_hito, creado_por)
