  (select uuid_new from _map_persona where legacy_id='1656'),
  'social', 'profesional', 'núcleo familiar compuesto por dos integrantes, referida tiene 77 años y su hermana quien se encuentra respaldad con credencial de cuidadora 63 años viven en domicilio propio de la hermana Malvina Saldias quienes como ingresos percibe su hermana pensión de viudez $120.000 y ella PGU $214.000 actualmente se atienden ambas en el hospital de Coinco, con hallazgo diabetes, insulino dependiente, insuficiencia renal grado 3 C y cardiovascular. la gran mayoría de los medicamentos e insumos deben ser comprados y también para alimentación por lo que sus egresos dando un total aprox $280.000. sae asigna la entrega de caja de mercaderia TODOS LOS MESES.', coalesce('2025-01-29'::date, current_date), current_setting('migracion.usuario')::uuid);
insert into public.hitos (grupo_familiar_id, persona_id, tipo, categoria, comentario, fecha_hito, creado_por)
values (
