-- ========== VERIFICACIÓN ==========
do $$
declare n_h int; n_p int; n_pn int; n_s int; n_e int; n_hi int; n_d int;
begin
  select count(*) into n_h  from public.grupos_familiares;
  select count(*) into n_p  from public.personas;
  select count(*) into n_pn from public.personas where grupo_familiar_id is null;
  select count(*) into n_s  from public.solicitudes where origen='migracion';
  select count(*) into n_e  from public.entregas;
  select count(*) into n_hi from public.hitos;
  select count(*) into n_d  from public.decisiones_solicitud;
  raise notice '=== RESULTADO MIGRACIÓN ===';
  raise notice 'Grupos familiares: % (esperado 1667)', n_h;
  raise notice 'Personas: % (esperado 1883)', n_p;
  raise notice 'Personas sin hogar: % (debe ser 0)', n_pn;
  raise notice 'Solicitudes migradas: % (esperado 13399)', n_s;
  raise notice 'Entregas: % (esperado 12100)', n_e;
  raise notice 'Decisiones: %', n_d;
  raise notice 'Hitos: % (esperado 4649)', n_hi;
  if n_pn > 0 then
    raise exception 'ABORTAR: % personas quedaron sin grupo_familiar_id', n_pn;
  end if;
  if n_h <> 1667 or n_p <> 1883 then
    raise warning 'Conteos base no coinciden con lo esperado. Revisa antes de confirmar.';
  end if;
end $$;

